using UnityEngine;
using UnityEngine.Audio;

namespace RealisticCarRacing.Audio
{
    public enum AudioCategory
    {
        Engine,
        Transmission,
        Tires,
        Environment,
        UI,
        Music
    }

    /// <summary>
    /// The game's mixer, its groups, the shared UI sounds and the default car sound set. Lives at
    /// Resources/Audio/GameAudio; generated by RealisticCarRacing &gt; Create Audio Content.
    /// </summary>
    [CreateAssetMenu(fileName = "GameAudio", menuName = "RealisticCarRacing/Game Audio")]
    public sealed class GameAudio : ScriptableObject
    {
        public const string ResourcePath = "Audio/GameAudio";

        public AudioMixer mixer;
        public AudioMixerGroup engine, transmission, tires, environment, ui, music;

        [Header("Vehicles")]
        public VehicleAudioProfile defaultVehicle;

        [Header("UI and race cues")]
        public AudioClip hover;
        public AudioClip click;
        public AudioClip back;
        public AudioClip countdownBeep;
        public AudioClip countdownGo;
        public AudioClip lapComplete;
        public AudioClip raceFinish;
        public AudioClip menuMusic;

        static GameAudio instance;
        static bool loaded;

        /// <summary>The project's audio setup, or null if it hasn't been generated (the game then runs silent).</summary>
        public static GameAudio Instance
        {
            get
            {
                if (!loaded)
                {
                    instance = Resources.Load<GameAudio>(ResourcePath);
                    loaded = true;
                }
                return instance;
            }
        }

        public AudioMixerGroup Group(AudioCategory category) => category switch
        {
            AudioCategory.Engine => engine,
            AudioCategory.Transmission => transmission,
            AudioCategory.Tires => tires,
            AudioCategory.Environment => environment,
            AudioCategory.UI => ui,
            _ => music
        };
    }
}
